  "use strict";

  const ANSWER_KEY = {
    q1: ["java", "rust"],
    q2: ["javascript", "webassembly", "typescript"],
    q3: ["haskell", "elixir", "scala"],
  };

  const QUESTION_LABELS = {
    q1: "Statically typed languages",
    q2: "Languages that run in a web browser",
    q3: "Languages with functional programming features",
  };

  const form = document.getElementById("quiz-form");
  const result = document.getElementById("result");

  function getSelections(name) {
    return Array.from(
      form.querySelectorAll('input[name="' + name + '"]:checked')
    ).map((el) => el.value);
  }

  function arraysEqualAsSets(a, b) {
    if (a.length !== b.length) return false;
    const setB = new Set(b);
    return a.every((v) => setB.has(v));
  }

  form.addEventListener("submit", function (e) {
    e.preventDefault();

    const items = [];
    let correctCount = 0;

    Object.keys(ANSWER_KEY).forEach((key) => {
      const picked = getSelections(key);
      const isCorrect = arraysEqualAsSets(picked, ANSWER_KEY[key]);
      if (isCorrect) correctCount++;
      items.push({ key, picked, isCorrect });
    });

    result.innerHTML = "";
    result.classList.add("show");

    const heading = document.createElement("h2");
    heading.textContent =
      "You scored " + correctCount + " out of " + Object.keys(ANSWER_KEY).length;
    result.appendChild(heading);

    const list = document.createElement("ul");
    items.forEach((item) => {
      const li = document.createElement("li");
      li.className = item.isCorrect ? "correct" : "incorrect";
      li.textContent =
        QUESTION_LABELS[item.key] +
        ": " +
        (item.isCorrect ? "Correct" : "Incorrect");
      list.appendChild(li);
    });
    result.appendChild(list);

    result.focus?.();
    result.scrollIntoView({ behavior: "smooth", block: "nearest" });
  });
})();
